import narwhals as nw


@nw.narwhalify
def add_total(df):
    return df.with_columns((nw.col("price") * nw.col("quantity")).alias("total"))


if __name__ == "__main__":
    import pandas as pd
    import polars as pl

    pdf = pd.DataFrame({"price": [10, 20, 30], "quantity": [1, 2, 3]})
    ldf = pl.DataFrame({"price": [10, 20, 30], "quantity": [1, 2, 3]})

    print(add_total(pdf))
    print(add_total(ldf))
